<?php
namespace App\Services;
use App\Models\Node;use App\Models\SystemIssue;use Illuminate\Http\Client\ConnectionException;use Illuminate\Http\Client\PendingRequest;use Illuminate\Http\Client\RequestException;use Illuminate\Support\Facades\Http;use Throwable;
final class DaemonClient{
private function client(Node $node,int $timeout=8):PendingRequest{return Http::baseUrl(sprintf('%s://%s:%d',$node->scheme,$node->fqdn,$node->daemon_port))->withToken($node->token)->acceptJson()->connectTimeout(3)->timeout($timeout);}
private function guarded(Node $node,?string $serverId,string $action,callable $callback):mixed{try{$result=$callback();SystemIssue::where('source','agent')->where('node_id',$node->id)->where('server_id',$serverId)->where('status','open')->whereIn('type',['node_connection_failed','agent_authentication_failed','agent_endpoint_missing','agent_internal_error','agent_request_failed','agent_error','agent_conflict','agent_validation_failed','node_timeout','node_connection_refused','node_dns_failed','node_tls_failed'])->get()->each(fn(SystemIssue $issue)=>$issue->resolveIssue());return $result;}catch(Throwable $e){[$type,$severity,$title,$message,$extra]=$this->diagnose($node,$action,$e);try{SystemIssue::report(source:'agent',title:$title,message:$message,severity:$severity,type:$type,nodeId:$node->id,serverId:$serverId,context:array_merge(['action'=>$action,'node'=>$node->name,'host'=>$node->fqdn,'port'=>$node->daemon_port,'scheme'=>$node->scheme,'exception'=>get_class($e)],$extra));}catch(Throwable){}throw $e;}}
private function diagnose(Node $node,string $action,Throwable $e):array{if($e instanceof ConnectionException){$raw=strtolower($e->getMessage());if(str_contains($raw,'timed out')||str_contains($raw,'timeout'))return['node_timeout','critical',"Timeout til {$node->name}",'Nodexa Agent svarede ikke inden timeout. Noden kan være overbelastet, offline eller blokeret af firewall.',[]];if(str_contains($raw,'connection refused'))return['node_connection_refused','critical',"Forbindelse afvist af {$node->name}",'Serveren kan nås, men Nodexa Agent lytter ikke på den konfigurerede port. Kontroller Agent-service og daemon-port.',[]];if(str_contains($raw,'could not resolve')||str_contains($raw,'name or service not known'))return['node_dns_failed','critical',"DNS-fejl på {$node->name}",'Node-hostnavnet kunne ikke slås op. Kontroller FQDN/DNS-indstillingerne.',[]];if(str_contains($raw,'ssl')||str_contains($raw,'certificate'))return['node_tls_failed','critical',"SSL/TLS-fejl på {$node->name}",'TLS-forbindelsen til Nodexa Agent kunne ikke valideres. Kontroller certifikat, hostname og HTTPS-konfiguration.',[]];return['node_connection_failed','critical',"Kan ikke forbinde til {$node->name}",'Panelet kunne ikke oprette forbindelse til Nodexa Agent: '.$e->getMessage(),[]];}if($e instanceof RequestException){$response=$e->response;$status=$response?->status();$body=trim((string)$response?->body());$extra=['http_status'=>$status,'response'=>mb_substr($body,0,4000)];if($status===401||$status===403)return['agent_authentication_failed','critical',"Agent-token afvist på {$node->name}",'Panelet kan nå Agenten, men autentificeringen blev afvist. Kontroller eller roter node-tokenet.',$extra];if($status===404)return['agent_endpoint_missing','error',"Agent endpoint mangler på {$node->name}","Agenten returnerede HTTP 404 under {$action}. Panel og Agent kan være på forskellige versioner.",$extra];if($status===409)return['agent_conflict','warning',"Konflikt på {$node->name}","Agenten returnerede HTTP 409 under {$action}. Handlingen konflikter med serverens nuværende tilstand.",$extra];if($status===422)return['agent_validation_failed','error',"Ugyldig Agent-request på {$node->name}","Agenten afviste data under {$action} med HTTP 422".($body!==''?': '.mb_substr($body,0,1000):'.'),$extra];if($status!==null&&$status>=500)return['agent_internal_error','critical',"Intern Agent-fejl på {$node->name}","Agenten returnerede HTTP {$status} under {$action}".($body!==''?': '.mb_substr($body,0,1000):'.'),$extra];if($status!==null)return['agent_request_failed','error',"Agent-request fejlede på {$node->name}","HTTP {$status} under {$action}".($body!==''?': '.mb_substr($body,0,1000):'.'),$extra];}return['agent_error','error',"Ukendt Agent-fejl på {$node->name}",$e->getMessage(),[]];}
private function serverPayload($server):array{$allocations=$server->allocations()->orderByDesc('is_primary')->get(['ip','port','is_primary'])->map(fn($a)=>['ip'=>$a->ip,'port'=>(int)$a->port,'is_primary'=>(bool)$a->is_primary])->values()->all();return['id'=>$server->uuid,'name'=>$server->name,'image'=>$server->docker_image,'startup'=>$server->startup,'template'=>$server->template_slug??'custom','memory_mb'=>$server->memory_mb,'disk_mb'=>$server->disk_mb,'cpu_limit'=>$server->cpu_limit,'environment'=>$server->environment??[],'allocations'=>$allocations];}
public function createServer($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'create_server',fn()=>$this->client($n,180)->post('/api/servers',$this->serverPayload($s))->throw()->json());}public function reinstall($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'reinstall_server',fn()=>$this->client($n,180)->post("/api/servers/{$s->uuid}/reinstall",$this->serverPayload($s))->throw()->json());}public function reconfigure($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'reconfigure_runtime',fn()=>$this->client($n,180)->put("/api/servers/{$s->uuid}/runtime",$this->serverPayload($s))->throw()->json());}
public function syncSftp($s,string $username,string $password):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'sync_sftp',fn()=>$this->client($n)->put("/api/servers/{$s->uuid}/sftp",['username'=>$username,'password'=>$password])->throw()->json());}public function deleteSftp($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'delete_sftp',fn()=>$this->client($n)->delete("/api/servers/{$s->uuid}/sftp")->throw()->json());}
public function power($s,string $signal):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'power:'.$signal,fn()=>$this->client($n)->post("/api/servers/{$s->uuid}/power",['signal'=>$signal])->throw()->json());}public function command($s,string $command):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'command',fn()=>$this->client($n)->post("/api/servers/{$s->uuid}/command",['command'=>$command])->throw()->json());}public function stats($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'stats',fn()=>$this->client($n)->get("/api/servers/{$s->uuid}/stats")->throw()->json());}public function logs($s,int $tail=200):string{$n=$s->node;return $this->guarded($n,(string)$s->id,'logs',fn()=>$this->client($n)->get("/api/servers/{$s->uuid}/logs",['tail'=>$tail])->throw()->body());}
public function streamLogs($s,int $tail,callable $write):void{$n=$s->node;$this->guarded($n,(string)$s->id,'stream_logs',function()use($n,$s,$tail,$write){$url=sprintf('%s://%s:%d/api/servers/%s/logs/stream?tail=%d',$n->scheme,$n->fqdn,$n->daemon_port,rawurlencode($s->uuid),max(0,min(1000,$tail)));$client=new \GuzzleHttp\Client(['connect_timeout'=>5,'timeout'=>0,'read_timeout'=>0,'http_errors'=>true]);$response=$client->request('GET',$url,['headers'=>['Authorization'=>'Bearer '.$n->token,'Accept'=>'text/plain'],'stream'=>true]);$body=$response->getBody();try{while(!$body->eof()){if(connection_aborted())break;$chunk=$body->read(32768);if($chunk===''){usleep(20000);continue;}$write($chunk);}}finally{$body->close();}return null;});}
public function files($s,string $path='/'):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'files',fn()=>$this->client($n)->get("/api/servers/{$s->uuid}/files",['path'=>$path])->throw()->json());}public function readFile($s,string $path):string{$n=$s->node;return $this->guarded($n,(string)$s->id,'read_file',fn()=>$this->client($n)->get("/api/servers/{$s->uuid}/files/content",['path'=>$path])->throw()->body());}public function writeFile($s,string $path,string $content):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'write_file',fn()=>$this->client($n)->withBody($content,'text/plain')->put("/api/servers/{$s->uuid}/files/content?path=".urlencode($path))->throw()->json());}public function mkdir($s,string $path):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'mkdir',fn()=>$this->client($n)->post("/api/servers/{$s->uuid}/files/directory",['path'=>$path])->throw()->json());}public function renameFile($s,string $from,string $to):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'rename_file',fn()=>$this->client($n)->post("/api/servers/{$s->uuid}/files/rename",['from'=>$from,'to'=>$to])->throw()->json());}public function uploadFile($s,string $directory,\Illuminate\Http\UploadedFile $file):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'upload_file',function()use($n,$s,$directory,$file){$h=fopen($file->getRealPath(),'rb');try{return $this->client($n,180)->attach('file',$h,$file->getClientOriginalName())->post("/api/servers/{$s->uuid}/files/upload",['path'=>$directory])->throw()->json();}finally{if(is_resource($h))fclose($h);}});}public function downloadFile($s,string $path):string{$n=$s->node;return $this->guarded($n,(string)$s->id,'download_file',fn()=>$this->client($n,120)->get("/api/servers/{$s->uuid}/files/download",['path'=>$path])->throw()->body());}public function archive($s,string $path):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'archive_file',fn()=>$this->client($n,120)->post("/api/servers/{$s->uuid}/files/archive",['path'=>$path])->throw()->json());}public function extract($s,string $path):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'extract_file',fn()=>$this->client($n,120)->post("/api/servers/{$s->uuid}/files/extract",['path'=>$path])->throw()->json());}public function deleteFile($s,string $path):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'delete_file',fn()=>$this->client($n)->delete("/api/servers/{$s->uuid}/files?path=".urlencode($path))->throw()->json());}
public function backups($s):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'list_backups',fn()=>$this->client($n)->get("/api/servers/{$s->uuid}/backups")->throw()->json());}public function backup($s,string $name):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'backup',fn()=>$this->client($n,180)->post("/api/servers/{$s->uuid}/backups",['name'=>$name])->throw()->json());}public function downloadBackup($s,string $name):string{$n=$s->node;return $this->guarded($n,(string)$s->id,'download_backup',fn()=>$this->client($n,180)->get("/api/servers/{$s->uuid}/backups/".rawurlencode($name))->throw()->body());}public function restoreBackup($s,string $name):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'restore_backup',fn()=>$this->client($n,180)->post("/api/servers/{$s->uuid}/backups/".rawurlencode($name).'/restore')->throw()->json());}public function deleteBackup($s,string $name):array{$n=$s->node;return $this->guarded($n,(string)$s->id,'delete_backup',fn()=>$this->client($n)->delete("/api/servers/{$s->uuid}/backups/".rawurlencode($name))->throw()->json());}
}
